using NUnit.Framework;
using System.Collections.Generic;

[TestFixture]
public class CountWordFrequencyTests
{
    [Test]
    public void Counts_Words_Ignoring_Case()
    {
        var result = CountWordFrequency("Hello hello world");
        Assert.That(result["hello"], Is.EqualTo(2));
        Assert.That(result["world"], Is.EqualTo(1));
    }

    private Dictionary<string, int> CountWordFrequency(string sentence)
    {
        var counts = new Dictionary<string, int>();

        foreach (var word in sentence.Split(' ', StringSplitOptions.RemoveEmptyEntries))
        {
            var normalized = word.ToLowerInvariant();
            counts[normalized] = counts.GetValueOrDefault(normalized) + 1;
        }

        return counts;
    }
}
